from collections import deque, defaultdict
H,W=len(test),len(test[0])
def comps(color, grid=test):
    cells={(r,c) for r in range(len(grid)) for c in range(len(grid[r])) if grid[r][c]==color}
    out=[]
    while cells:
        start=cells.pop(); q=[start]; cc={start}
        while q:
            r,c=q.pop()
            for nb in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                if nb in cells:
                    cells.remove(nb); cc.add(nb); q.append(nb)
        out.append(cc)
    return sorted(out,key=lambda x:min(x))
for color in sorted({x for row in test for x in row if x not in (0,2)}):
    for i,cc in enumerate(comps(color)):
        rs=[r for r,c in cc]; cs=[c for r,c in cc]
        near=set()
        for r,c in cc:
            for nr,nc in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                if 0<=nr<H and 0<=nc<W and test[nr][nc]==2: near.add((nr,nc))
        print(color,i,'bbox', (min(rs),max(rs),min(cs),max(cs)), 'shape',sorted((r-min(rs),c-min(cs)) for r,c in cc),'adj2',sorted(near))

cc_by = {}
for color in [1,3,4,5,8,9]: cc_by[color]=comps(color)
placements = {(1,0):(1,15),(3,0):(3,15),(4,0):(11,12),(5,0):(17,6),(8,0):(8,15),(9,0):(14,10),(9,1):(14,6)}
# collect all source components and assign each adjacent 2 marker to component(s)
marker_owner=defaultdict(list)
for color, ccs in cc_by.items():
    for i,cc in enumerate(ccs):
        for r,c in cc:
            for nr,nc in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                if 0<=nr<H and 0<=nc<W and test[nr][nc]==2:
                    marker_owner[(nr,nc)].append((color,i))
print('unclaimed', sorted((r,c) for r in range(H) for c in range(W) if test[r][c]==2 and (r,c) not in marker_owner))
print('multiply', {p:o for p,o in marker_owner.items() if len(o)>1})
# translate body plus adjacent markers
out=[[0]*W for _ in range(H)]
for color,ccs in cc_by.items():
    for i,cc in enumerate(ccs):
        tr,tc=placements[(color,i)]
        rs=[r for r,c in cc]; cs=[c for r,c in cc]
        r0,c0=min(rs),min(cs)
        dr,dc=tr-r0,tc-c0
        for r,c in cc:
            rr,ccol=r+dr,c+dc
            assert out[rr][ccol] in (0,color), (rr,ccol,out[rr][ccol],color)
            out[rr][ccol]=color
        for (mr,mc),owners in marker_owner.items():
            if (color,i) in owners:
                rr,ccol=mr+dr,mc+dc
                if out[rr][ccol]==0: out[rr][ccol]=2
                # colored bodies later overwrite marks
print('nonzero counts',Counter(x for row in out for x in row))
print('\n'.join(' '.join(map(str,row)) for row in out))

